  41: @Service
  42: public class FrameCsvImportService {
  43: 
  44:     private static final Set<String> REQUIRED_HEADERS = Set.of(
  45:         "frame_id", "type_classic_digital", "format", "status",
  46:         "postcode", "site_no", "region", "town"
  47:     );
  48: 
  49:     private static final CSVFormat CSV_FORMAT = CSVFormat.DEFAULT.builder()
  50:         .setHeader()
  51:         .setSkipHeaderRecord(true)
  52:         .setIgnoreEmptyLines(true)
  53:         .setDuplicateHeaderMode(DuplicateHeaderMode.DISALLOW)
  54:         .get();
  55: 
  56:     private final FrameService frameService;
  57:     private final Validator validator;
  58: 
  59:     public FrameCsvImportService(FrameService frameService, Validator validator) {
  60:         this.frameService = frameService;
  61:         this.validator = validator;
  62:     }
  63: 
  64:     public FrameCsvImportSummary importCsv(MultipartFile file) {
  65:         List<CSVRecord> records = parse(file);
  66:         Set<String> seenFrameIds = new HashSet<>();
  67:         List<FrameCsvImportError> errors = new ArrayList<>();
  68:         int created = 0;
  69:         int duplicates = 0;
  70:         int failed = 0;
  71: 
  72:         for (CSVRecord record : records) {
  73:             long rowNumber = record.getRecordNumber() + 1;
  74:             String frameId = value(record, "frame_id");
  75: 
  76:             if (frameId != null && !seenFrameIds.add(frameId)) {
  77:                 duplicates++;
  78:                 errors.add(new FrameCsvImportError(
  79:                     rowNumber,
  80:                     frameId,
  81:                     "frameId appears more than once in the CSV"
  82:                 ));
  83:                 continue;
  84:             }
  85: 
  86:             try {
  87:                 CreateFrameRequest request = toRequest(record);
  88:                 validate(request);
  89:                 frameService.createImportedFrame(request);
  90:                 created++;
  91:             } catch (DuplicateFrameException exception) {
  92:                 duplicates++;
  93:                 errors.add(new FrameCsvImportError(rowNumber, frameId, exception.getMessage()));
  94:             } catch (RowImportException exception) {
  95:                 failed++;
  96:                 errors.add(new FrameCsvImportError(rowNumber, frameId, exception.getMessage()));
  97:             } catch (DataAccessException exception) {
  98:                 failed++;
  99:                 errors.add(new FrameCsvImportError(rowNumber, frameId, "Frame could not be persisted"));
 100:             }
 101:         }
 102: 
 103:         return new FrameCsvImportSummary(records.size(), created, duplicates, failed, errors);
 104:     }
 105: 
 106:     private List<CSVRecord> parse(MultipartFile file) {
 107:         if (file == null || file.isEmpty()) {
 108:             throw new InvalidCsvFileException("CSV file is empty");
 109:         }
 110: 
 111:         String content = decode(file);
 112:         if (content.startsWith("\uFEFF")) {
 113:             content = content.substring(1);
 114:         }
 115:         if (content.isBlank()) {
 116:             throw new InvalidCsvFileException("CSV file is empty");
 117:         }
 118: 
 119:         try (CSVParser parser = CSV_FORMAT.parse(new StringReader(content))) {
 120:             Map<String, Integer> headers = parser.getHeaderMap();
 121:             Set<String> missingHeaders = REQUIRED_HEADERS.stream()
 122:                 .filter(header -> !headers.containsKey(header))
 123:                 .collect(Collectors.toCollection(java.util.TreeSet::new));
 124:             if (!missingHeaders.isEmpty()) {
 125:                 throw new InvalidCsvFileException(
 126:                     "CSV is missing required headers: " + String.join(", ", missingHeaders)
 127:                 );
 128:             }
 129: 
 130:             List<CSVRecord> records = parser.getRecords();
 131:             if (records.isEmpty()) {
 132:                 throw new InvalidCsvFileException("CSV contains no data rows");
 133:             }
 134:             for (CSVRecord record : records) {
 135:                 if (record.size() != headers.size()) {
 136:                     throw new InvalidCsvFileException(
 137:                         "CSV row " + (record.getRecordNumber() + 1)
 138:                             + " has a different number of columns than the header"
 139:                     );
 140:                 }
 141:             }
 142:             return records;
 143:         } catch (InvalidCsvFileException exception) {
 144:             throw exception;
 145:         } catch (IOException | UncheckedIOException | IllegalArgumentException exception) {
 146:             throw new InvalidCsvFileException("CSV content is malformed", exception);
 147:         }
 148:     }
 149: 
 150:     private String decode(MultipartFile file) {
 151:         try {
 152:             byte[] bytes = file.getBytes();
 153:             return StandardCharsets.UTF_8.newDecoder()
 154:                 .onMalformedInput(CodingErrorAction.REPORT)
 155:                 .onUnmappableCharacter(CodingErrorAction.REPORT)
 156:                 .decode(ByteBuffer.wrap(bytes))
 157:                 .toString();
 158:         } catch (CharacterCodingException exception) {
 159:             throw new InvalidCsvFileException("CSV content is not valid UTF-8", exception);
 160:         } catch (IOException exception) {
 161:             throw new InvalidCsvFileException("CSV file could not be read", exception);
 162:         }
 163:     }
