 165:     private CreateFrameRequest toRequest(CSVRecord record) {
 166:         return new CreateFrameRequest(
 167:             value(record, "frame_id"),
 168:             value(record, "type_classic_digital"),
 169:             value(record, "format"),
 170:             value(record, "environment"),
 171:             value(record, "status"),
 172:             value(record, "status_reason"),
 173:             new LocationDto(
 174:                 value(record, "postcode"),
 175:                 value(record, "postcode_area"),
 176:                 value(record, "postcode_district"),
 177:                 value(record, "postcode_sector"),
 178:                 value(record, "postcode_unit"),
 179:                 value(record, "address"),
 180:                 value(record, "region"),
 181:                 value(record, "country_code"),
 182:                 value(record, "town"),
 183:                 decimal(record, "longitude"),
 184:                 decimal(record, "latitude"),
 185:                 integer(record, "distance_to_closest_school"),
 186:                 value(record, "location"),
 187:                 value(record, "location_id")
 188:             ),
 189:             new SiteDto(
 190:                 value(record, "site_no"),
 191:                 value(record, "inventory_site_no"),
 192:                 value(record, "panel_number"),
 193:                 value(record, "station"),
 194:                 value(record, "airport")
 195:             ),
 196:             new TechnicalDto(
 197:                 value(record, "illumination_type_id"),
 198:                 integer(record, "number_of_slots"),
 199:                 value(record, "size_code"),
 200:                 value(record, "size_group_code"),
 201:                 value(record, "aspect_ratio_code"),
 202:                 value(record, "t_size"),
 203:                 integer(record, "pixel_height"),
 204:                 integer(record, "pixel_width")
 205:             ),
 206:             new CommercialDto(
 207:                 decimal(record, "impact_weight"),
 208:                 value(record, "production_rate_card"),
 209:                 value(record, "production_rate_card_legacy"),
 210:                 value(record, "pricing_grade"),
 211:                 value(record, "price_entity_id"),
 212:                 bool(record, "premium")
 213:             ),
 214:             new IntegrationDto(
 215:                 value(record, "broadsign_display_unit_id"),
 216:                 value(record, "broadsign_frame_id"),
 217:                 value(record, "broadsign_domain_id"),
 218:                 value(record, "linked_frame_ids")
 219:             )
 220:         );
 221:     }
 222: 
 223:     private void validate(CreateFrameRequest request) {
 224:         String reason = validator.validate(request).stream()
 225:             .sorted(Comparator.comparing(violation -> violation.getPropertyPath().toString()))
 226:             .map(this::validationMessage)
 227:             .collect(Collectors.joining("; "));
 228:         if (!reason.isEmpty()) {
 229:             throw new RowImportException(reason);
 230:         }
 231:     }
 232: 
 233:     private String validationMessage(ConstraintViolation<CreateFrameRequest> violation) {
 234:         return violation.getPropertyPath() + " " + violation.getMessage();
 235:     }
 236: 
 237:     private String value(CSVRecord record, String header) {
 238:         if (!record.isMapped(header)) {
 239:             return null;
 240:         }
 241:         String value = record.get(header).trim();
 242:         return value.isEmpty() ? null : value;
 243:     }
 244: 
 245:     private Integer integer(CSVRecord record, String header) {
 246:         String value = value(record, header);
 247:         if (value == null) {
 248:             return null;
 249:         }
 250:         try {
 251:             return Integer.valueOf(value);
 252:         } catch (NumberFormatException exception) {
 253:             throw new RowImportException(header + " must be a whole number");
 254:         }
 255:     }
 256: 
 257:     private BigDecimal decimal(CSVRecord record, String header) {
 258:         String value = value(record, header);
 259:         if (value == null) {
 260:             return null;
 261:         }
 262:         try {
 263:             return new BigDecimal(value);
 264:         } catch (NumberFormatException exception) {
 265:             throw new RowImportException(header + " must be a decimal number");
 266:         }
 267:     }
 268: 
 269:     private Boolean bool(CSVRecord record, String header) {
 270:         String value = value(record, header);
 271:         if (value == null) {
 272:             return null;
 273:         }
 274:         return switch (value.toLowerCase(java.util.Locale.ROOT)) {
 275:             case "1", "true" -> true;
 276:             case "0", "false" -> false;
 277:             default -> throw new RowImportException(header + " must be 0, 1, true, or false");
 278:         };
 279:     }
 280: 
 281:     private static class RowImportException extends RuntimeException {
 282: 
 283:         RowImportException(String message) {
 284:             super(message);
 285:         }
 286:     }
 287: }
