 269:     private Boolean bool(CSVRecord record, String header) {
 270:         String value = value(record, header);
 271:         if (value == null) {
 272:             return null;
 273:         }
 274:         return switch (value.toLowerCase(java.util.Locale.ROOT)) {
 275:             case "1", "true" -> true;
 276:             case "0", "false" -> false;
 277:             default -> throw new RowImportException(header + " must be 0, 1, true, or false");
 278:         };
 279:     }
