 223:     private void validate(CreateFrameRequest request) {
 224:         String reason = validator.validate(request).stream()
 225:             .sorted(Comparator.comparing(violation -> violation.getPropertyPath().toString()))
 226:             .map(this::validationMessage)
 227:             .collect(Collectors.joining("; "));
 228:         if (!reason.isEmpty()) {
 229:             throw new RowImportException(reason);
 230:         }
 231:     }
 232: 
 233:     private String validationMessage(ConstraintViolation<CreateFrameRequest> violation) {
 234:         return violation.getPropertyPath() + " " + violation.getMessage();
 235:     }
