 237:     private String value(CSVRecord record, String header) {
 238:         if (!record.isMapped(header)) {
 239:             return null;
 240:         }
 241:         String value = record.get(header).trim();
 242:         return value.isEmpty() ? null : value;
 243:     }
 244: 
 245:     private Integer integer(CSVRecord record, String header) {
 246:         String value = value(record, header);
 247:         if (value == null) {
 248:             return null;
 249:         }
 250:         try {
 251:             return Integer.valueOf(value);
 252:         } catch (NumberFormatException exception) {
 253:             throw new RowImportException(header + " must be a whole number");
 254:         }
 255:     }
 256: 
 257:     private BigDecimal decimal(CSVRecord record, String header) {
 258:         String value = value(record, header);
 259:         if (value == null) {
 260:             return null;
 261:         }
 262:         try {
 263:             return new BigDecimal(value);
 264:         } catch (NumberFormatException exception) {
 265:             throw new RowImportException(header + " must be a decimal number");
 266:         }
 267:     }
 268: 
 269:     private Boolean bool(CSVRecord record, String header) {
 270:         String value = value(record, header);
 271:         if (value == null) {
 272:             return null;
 273:         }
 274:         return switch (value.toLowerCase(java.util.Locale.ROOT)) {
 275:             case "1", "true" -> true;
 276:             case "0", "false" -> false;
 277:             default -> throw new RowImportException(header + " must be 0, 1, true, or false");
 278:         };
 279:     }
 280: 
 281:     private static class RowImportException extends RuntimeException {
 282: 
 283:         RowImportException(String message) {
 284:             super(message);
 285:         }
 286:     }
 287: }
