  68:                 "message", error.getDefaultMessage() == null ? "is invalid" : error.getDefaultMessage()
  69:             ))
  70:             .toList();
  71:         ResponseEntity<ProblemDetail> response = problem(
  72:             HttpStatus.BAD_REQUEST,
  73:             "Validation failed",
  74:             "One or more fields are invalid",
  75:             request
  76:         );
