 117:         );
 118:         ResponseEntity.BodyBuilder response = ResponseEntity.status(HttpStatus.METHOD_NOT_ALLOWED);
 119:         if (exception.getSupportedHttpMethods() != null) {
 120:             response.allow(exception.getSupportedHttpMethods().toArray(HttpMethod[]::new));
 121:         }
 122:         return response.body(problem);
