 135:         );
 136:         ResponseEntity.BodyBuilder response = ResponseEntity.status(HttpStatus.UNSUPPORTED_MEDIA_TYPE);
 137:         if (!exception.getSupportedMediaTypes().isEmpty()) {
 138:             response.header(HttpHeaders.ACCEPT, MediaType.toString(exception.getSupportedMediaTypes()));
 139:         }
 140:         return response.body(problem);
