 156:     private ResponseEntity<ProblemDetail> problem(
 157:         HttpStatus status,
 158:         String title,
 159:         String detail,
 160:         HttpServletRequest request
 161:     ) {
 162:         return ResponseEntity.status(status).body(problemDetail(status, title, detail, request));
 163:     }
 164: 
 165:     private ProblemDetail problemDetail(
 166:         HttpStatus status,
 167:         String title,
 168:         String detail,
 169:         HttpServletRequest request
 170:     ) {
 171:         ProblemDetail problem = ProblemDetail.forStatusAndDetail(status, detail);
 172:         problem.setTitle(title);
 173:         problem.setInstance(URI.create(request.getRequestURI()));
 174:         return problem;
 175:     }
