package com.global.ct.frameinventory.logging;

public final class LogValueSanitizer {

    static final int MAX_LENGTH = 256;
    private static final String TRUNCATION_MARKER = "...";

    private LogValueSanitizer() {
    }

    public static String sanitize(String value) {
        if (value == null) {
            return "<null>";
        }

        int codePointCount = value.codePointCount(0, value.length());
        boolean truncated = codePointCount > MAX_LENGTH;
        int contentLength = truncated ? MAX_LENGTH - TRUNCATION_MARKER.length() : MAX_LENGTH;
        StringBuilder sanitized = new StringBuilder(Math.min(value.length(), MAX_LENGTH));

        value.codePoints()
            .limit(contentLength)
            .forEach(codePoint -> sanitized.appendCodePoint(
                isUnsafe(codePoint) ? '_' : codePoint
            ));

        if (truncated) {
            sanitized.append(TRUNCATION_MARKER);
        }
        return sanitized.toString();
    }

    private static boolean isUnsafe(int codePoint) {
        int type = Character.getType(codePoint);
        return Character.isISOControl(codePoint)
            || type == Character.FORMAT
            || type == Character.LINE_SEPARATOR
            || type == Character.PARAGRAPH_SEPARATOR
            || type == Character.SURROGATE;
    }
}

package com.global.ct.frameinventory.logging;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class LogValueSanitizerTest {

    @Test
    void replacesControlAndFormattingCharacters() {
        String value = "safe\r\n\t\u0000\u001B\u007F\u0085\u2028\u2029\u202Eend";

        assertThat(LogValueSanitizer.sanitize(value)).isEqualTo("safe__________end");
    }

    @Test
    void truncatesLongValuesToTheMaximumLength() {
        String sanitized = LogValueSanitizer.sanitize("a".repeat(300));

        assertThat(sanitized)
            .hasSize(LogValueSanitizer.MAX_LENGTH)
            .endsWith("...");
    }

    @Test
    void representsNullWithoutLoggingTheLiteralValue() {
        assertThat(LogValueSanitizer.sanitize(null)).isEqualTo("<null>");
    }
}

